-- Dati DEMO per la prova del Direttivo. Tutti riconoscibili: id 'demo-…' (testo) o 'de000000-…' (uuid).
-- Rimozione: supabase/remove-demo.sql
begin;
set local session_replication_role=replica; -- inserimento diretto: niente trigger (date passate, audit, collegamenti automatici)
update public.members m set fav_game_id=null where m.id like 'demo-m%' and not exists(select 1 from public.games g where g.id=m.fav_game_id);
set local session_replication_role=origin;
commit;
